mapper.select:
SELECT i.*, p.name as product_name, p.image as product_image FROM inventory i LEFT JOIN product p ON i.product_id = p.id WHERE i.deleted = 0 AND (p.deleted = 0 OR p.deleted IS NULL) AND i.quantity <= i.warning_quantity
AND p.merchant_id = #{merchantId}
ORDER BY (i.warning_quantity - i.quantity) DESC

SELECT i.*, p.name as product_name, p.image as product_image FROM inventory i LEFT JOIN product p ON i.product_id = p.id WHERE i.deleted = 0 AND (p.deleted = 0 OR p.deleted IS NULL)
AND p.merchant_id = #{merchantId}
AND (p.name LIKE CONCAT('%', #{keyword}, '%') OR i.product_id = #{keyword})
ORDER BY i.create_time DESC LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM inventory i LEFT JOIN product p ON i.product_id = p.id WHERE i.deleted = 0 AND (p.deleted = 0 OR p.deleted IS NULL)
AND p.merchant_id = #{merchantId}
AND (p.name LIKE CONCAT('%', #{keyword}, '%') OR i.product_id = #{keyword})
